const isNeighbor = ([x, y]: Cell, other: Cell): boolean =>
  isWithinOneStep(x, other[0]) &&
  isWithinOneStep(y, other[1]) &&
  !isSameCell([x, y], other);

const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((other) => isNeighbor(cell, other)).length;

const survives = (neighborCount: number): boolean =>
  neighborCount === 2 || neighborCount === 3;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(countLiveNeighbors(cell, liveCells)));
}
